// UserPromptSubmit hook: inject a warning when the dispatch-watchdog cache
// (mt#2646) has flagged an IN-PROGRESS/IN-REVIEW task whose subagent dispatch
// has gone silent (no commit, no PR/system event, no subagent_invocations
// progress) for the stale window — the CONSUMER side of the producer/
// consumer cached-injection mechanism.
//
// Why this exists. During the mt#2607 burndown (~14 implementer dispatches,
// 2026-07-06/07), 5 dispatches ended without a usable completion report — two
// stalled silently mid-review-convergence for 6.5h, one died with
// uncommitted work and no handoff, one died on an API error mid-convergence.
// Every case required the orchestrator to manually notice the silence and
// probe session state. This hook surfaces the same signal structurally,
// every turn, instead of relying on the orchestrator remembering to check.
//
// Cost discipline (mirrors inject-prod-state.ts / memory 08606f7c): a per-turn
// DB + git query fails the cheap/non-churny injection bar. So this hook reads
// ONLY a local cache file — the PRODUCER (`src/cockpit/dispatch-watchdog.ts`,
// driven by the cockpit cadence sweep `startDispatchWatchdogSweeper`) does the
// periodic DB/git read and writes the cache.
//
// Override: MINSKY_SKIP_DISPATCH_WATCHDOG_INJECTION=1|true|yes skips
// injection with an audit-log line to stdout.
//
// @see mt#2646 — this hook
// @see src/cockpit/dispatch-watchdog.ts — the producer (refresh + cache write)
// @see mt#2506 .minsky/hooks/inject-prod-state.ts — sibling producer/consumer pattern
// @see memory 08606f7c — structural-injection rule this hook instantiates

import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import { readInput, writeOutput } from "./types";
import type { ClaudeHookInput, HookOutput } from "./types";
import type { DispatchContext, GuardOutcome } from "./registry";

export const DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV = "MINSKY_SKIP_DISPATCH_WATCHDOG_INJECTION";

// Cache location — MUST match `src/cockpit/dispatch-watchdog.ts`
// (DISPATCH_WATCHDOG_CACHE_FILENAME + getStateDir). That module lives in a
// separate module graph and cannot be imported here, so the path resolution
// is duplicated; keep the two in sync.
const DISPATCH_WATCHDOG_CACHE_FILENAME = "dispatch-watchdog-cache.json";

/** Resolve the Minsky state dir: MINSKY_STATE_DIR, else XDG_STATE_HOME/minsky, else ~/.local/state/minsky. */
function getStateDir(): string {
  const override = process.env["MINSKY_STATE_DIR"];
  if (override) return override;
  const xdgStateHome =
    process.env["XDG_STATE_HOME"] || path.join(process.env["HOME"] || os.homedir(), ".local/state");
  return path.join(xdgStateHome, "minsky");
}

function getDispatchWatchdogCachePath(): string {
  return path.join(getStateDir(), DISPATCH_WATCHDOG_CACHE_FILENAME);
}

export interface UserPromptSubmitInput extends ClaudeHookInput {
  prompt: string;
}

/**
 * Which signal produced a flag's `lastActivityAt` (mt#3172; mt#3193 adds
 * `"workspace-mtime"`; mirrors src/cockpit/dispatch-watchdog.ts's
 * DispatchWatchdogActivitySource — this hook duplicates the shape rather
 * than importing it, per this file's module-graph-isolation convention, see
 * the cache-path comment above).
 */
export type DispatchWatchdogActivitySourceRecord =
  | "dispatch-start"
  | "commit"
  | "event"
  | "presence"
  | "workspace-mtime";

/**
 * Runtime-reflectable enumeration of every recognized value (PR #2307 R1
 * non-blocking) — kept in lockstep with `DISPATCH_WATCHDOG_ACTIVITY_SOURCES`
 * in `src/cockpit/dispatch-watchdog.ts` via a cross-module parity TEST
 * (`inject-dispatch-watchdog.test.ts`), NOT via a shared import (this file
 * deliberately does not import from `src/cockpit/*` — see the cache-path
 * comment above). Add a new value here AND there, in the same PR, or the
 * parity test fails.
 */
export const RECOGNIZED_ACTIVITY_SOURCES = [
  "dispatch-start",
  "commit",
  "event",
  "presence",
  "workspace-mtime",
] as const satisfies readonly DispatchWatchdogActivitySourceRecord[];

/** One flagged dispatch (mirrors src/cockpit/dispatch-watchdog.ts DispatchWatchdogFlag). */
export interface DispatchWatchdogFlagRecord {
  taskId: string;
  subagentSessionId: string | null;
  agentType: string;
  taskStatus: string;
  startedAt: string;
  lastActivityAt: string;
  staleForMs: number;
  /** Which signal produced lastActivityAt — surfaced in the banner so a flagged dispatch stays diagnosable (mt#3172). */
  activitySource: DispatchWatchdogActivitySourceRecord;
}

/** The on-disk cache record (mirrors src/cockpit/dispatch-watchdog.ts DispatchWatchdogSnapshot). */
export interface DispatchWatchdogCacheRecord {
  checkedAt: string;
  staleMs: number;
  flags: DispatchWatchdogFlagRecord[];
}

/**
 * Parse + validate the cache JSON. Returns null on malformed/invalid content so the hook
 * fails open (treats it as "no signal" rather than crashing). Pure function for testability.
 */
export function parseDispatchWatchdogCache(raw: string): DispatchWatchdogCacheRecord | null {
  let obj: unknown;
  try {
    obj = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!obj || typeof obj !== "object") return null;
  const rec = obj as Record<string, unknown>;
  if (typeof rec.checkedAt !== "string" || rec.checkedAt.length === 0) return null;
  if (typeof rec.staleMs !== "number" || !Number.isFinite(rec.staleMs)) return null;
  if (!Array.isArray(rec.flags)) return null;

  const flags: DispatchWatchdogFlagRecord[] = [];
  for (const raw of rec.flags) {
    if (!raw || typeof raw !== "object") continue;
    const f = raw as Record<string, unknown>;
    if (typeof f.taskId !== "string") continue;
    if (typeof f.agentType !== "string") continue;
    if (typeof f.taskStatus !== "string") continue;
    if (typeof f.startedAt !== "string") continue;
    if (typeof f.lastActivityAt !== "string") continue;
    if (typeof f.staleForMs !== "number" || !Number.isFinite(f.staleForMs)) continue;
    const sid = f.subagentSessionId;
    // mt#3172: normalize a missing/unrecognized activitySource (e.g. a cache
    // file written by a producer build that predates this field, during a
    // rollout window) to "dispatch-start" rather than dropping the whole
    // flag entry — mirrors the subagentSessionId normalization above.
    // Checked against RECOGNIZED_ACTIVITY_SOURCES (single source of truth
    // for this file, kept in lockstep with the producer's own list via the
    // cross-module parity test — see that const's docstring) rather than a
    // hardcoded chain, so adding a new signal only requires updating one
    // array here, not a scattered condition.
    const rawSource = f.activitySource;
    const activitySource: DispatchWatchdogActivitySourceRecord =
      typeof rawSource === "string" &&
      (RECOGNIZED_ACTIVITY_SOURCES as readonly string[]).includes(rawSource)
        ? (rawSource as DispatchWatchdogActivitySourceRecord)
        : "dispatch-start";
    flags.push({
      taskId: f.taskId,
      subagentSessionId: typeof sid === "string" ? sid : null,
      agentType: f.agentType,
      taskStatus: f.taskStatus,
      startedAt: f.startedAt,
      lastActivityAt: f.lastActivityAt,
      staleForMs: f.staleForMs,
      activitySource,
    });
  }
  return { checkedAt: rec.checkedAt, staleMs: rec.staleMs, flags };
}

/** Humanize a duration in ms to a compact "Nm" / "Nh" / "Nd" string (floored, min "0m"). */
export function formatAge(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return "unknown";
  const mins = Math.floor(ms / 60000);
  if (mins < 60) return `${mins}m`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h`;
  return `${Math.floor(hours / 24)}d`;
}

/**
 * Cap on how many flagged dispatches the banner enumerates before eliding the
 * rest as "+N more" (mt#3485).
 *
 * Grounded in observed cadence rather than a round number
 * (`decision-defaults.mdc §Thresholds`): the largest simultaneous flag set this
 * watchdog has produced is FOUR (mt#3193, four IN-REVIEW dispatches flagged in
 * one run), and the largest dispatch fleet on record is the mt#2607 burndown's
 * ~14 dispatches, of which 5 ended without a usable completion report. A cap of
 * 5 therefore covers the worst observed simultaneous-flag event with headroom
 * and bounds the worst observed fleet-wide case, while capping this guard's
 * contribution to the merged injection budget — which is the point, since the
 * banner's per-dispatch term is the only part of it that scales with input.
 */
const MAX_ENUMERATED_FLAGS = 5;

/**
 * Format the dispatch-watchdog snapshot into the additionalContext payload.
 *
 * Advisory-text provenance (kept here, not in the injection, per
 * `.minsky/rules/guard-feedback-authoring.mdc`): the recover/escalate branch
 * semantics come from `tasks.dispatch-recover` (mt#2831), which captures
 * session state (git-diff presence, commits-ahead-of-base, handoff.md),
 * classifies per the subagent-outcome taxonomy, and enforces the 2-attempt
 * bound server-side. `escalate` means that bound is reached — no further AUTO
 * resume — NOT that the dispatch is dead; mt#3204 established that
 * `dirtyFileCount` / `gitStatus` / `workspaceMtimeAgoMs` are the discriminating
 * signals there, because push/PR/review activity goes quiet while an agent
 * edits files it has not committed yet.
 *
 * Three shapes:
 *   - null cache (no snapshot yet) → silent (no known-flaggable state; the
 *     producer may just not have ticked yet — this is NOT the same failure
 *     class as inject-prod-state's UNKNOWN, since an empty watchdog is the
 *     overwhelmingly common healthy case and warning on every turn before
 *     the first sweep tick would be pure noise).
 *   - empty flags → silent (nothing stalled).
 *   - non-empty flags → a warning naming each flagged dispatch with a
 *     recovery pointer (probe via session.status, resume protocol in
 *     /orchestrate).
 *
 * Pure function for testability; the entrypoint feeds it the parsed cache.
 */
export function formatDispatchWatchdogState(
  record: DispatchWatchdogCacheRecord | null
): string | null {
  if (record === null) return null;
  if (record.flags.length === 0) return null;

  const lines = record.flags.map((f) => {
    const age = formatAge(f.staleForMs);
    const sidStr = f.subagentSessionId ?? "(no session id)";
    // mt#3172: name the freshest signal consulted (parity with
    // tasks.dispatch-recover's activitySource field) so a flagged dispatch
    // stays diagnosable — e.g. distinguishing "nothing since dispatch start"
    // from "a commit landed but it's still stale" from "presence activity
    // was seen but it's still stale."
    // `lastActivityAt` is deliberately NOT rendered (mt#3485): the header
    // already carries `checkedAt` and this line carries the silent-for age, so
    // the absolute timestamp is derivable from the two — and at ~40 chars on
    // the one part of this banner that scales per dispatch, it was the most
    // expensive derivable field in the whole injection.
    // PR #2499 R1: `agentType=` keeps its label. The first draft dropped it to
    // save ~10 chars/line, but the labelled `field=value` form is what makes
    // this line scannable, and no consumer had to be broken to save 50 chars at
    // the cap. `lastActivityAt` stays dropped — that one is genuinely derivable.
    return `  - ${f.taskId} (${f.taskStatus}, agentType=${f.agentType}, session=${sidStr}): silent ${age}, source=${f.activitySource}`;
  });

  const shown = lines.slice(0, MAX_ENUMERATED_FLAGS);
  if (lines.length > MAX_ENUMERATED_FLAGS) {
    shown.push(
      `  ... +${lines.length - MAX_ENUMERATED_FLAGS} more (${MAX_ENUMERATED_FLAGS} of ${lines.length} shown)`
    );
  }

  return (
    `DISPATCH WATCHDOG: ${record.flags.length} in-flight subagent dispatch(es) silent past the ` +
    `stale window (checked ${record.checkedAt}):\n${shown.join("\n")}\n` +
    "Call the tasks.dispatch-recover MCP tool with each flagged taskId — do not hand-roll a " +
    "probe-then-decide sequence — and branch on its `status`: `recover` -> redispatch the " +
    "returned `continuationPrompt` VERBATIM via the Agent tool into the SAME session; " +
    "`escalate` -> read `escalation.probe` first, because `dirtyFileCount` / `gitStatus` / " +
    "`workspaceMtimeAgoMs` discriminate 'working locally' from 'dead' and push/PR/review " +
    "quiet does not. `contested` -> do NOT redispatch: a live peer holds the task's claim " +
    "(or the claim store was unreadable and this failed closed), so a redispatch would " +
    "collide with a live actor — surface `peerActorId` to the operator instead. If it " +
    "returns `healthy` or `not-in-flight`, the flag was a false " +
    "positive and no action is needed. Full protocol: the /orchestrate skill's \"Dispatch " +
    'watchdog and resume protocol".'
  );
}

function isOverrideTruthy(value: string | undefined): boolean {
  if (!value) return false;
  const v = value.toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

/**
 * The three distinguishable read outcomes for the cache file. "missing" and
 * "malformed" are both fail-open for the additionalContext path (neither
 * blocks the prompt), but they are NOT the same failure class: "missing"
 * is the routine pre-first-sweep-tick state (silent, expected); "malformed"
 * means the file exists but the producer wrote something the consumer can't
 * parse — a real signal worth an audit line (R1 non-blocking #1).
 */
export type CacheReadResult =
  | { kind: "missing" }
  | { kind: "malformed" }
  | { kind: "ok"; record: DispatchWatchdogCacheRecord };

/** Read + parse the cache file, distinguishing "absent" from "present but malformed". */
export function readCache(cachePath: string): CacheReadResult {
  let exists: boolean;
  try {
    exists = fs.existsSync(cachePath);
  } catch {
    return { kind: "missing" };
  }
  if (!exists) return { kind: "missing" };

  let raw: string;
  try {
    raw = fs.readFileSync(cachePath, { encoding: "utf8" });
  } catch {
    // Existed at the existsSync check but became unreadable (permissions,
    // TOCTOU race, transient FS error) — treat as malformed, not missing:
    // the file IS there and something about it prevented a read.
    return { kind: "malformed" };
  }

  const record = parseDispatchWatchdogCache(raw);
  return record === null ? { kind: "malformed" } : { kind: "ok", record };
}

/**
 * Dispatcher-compatible pure function (ADR-028 Phase 2b, mt#2687). Mirrors
 * `main()`'s orchestration but returns a `GuardOutcome` instead of writing to
 * stdout / calling `process.exit`. A "malformed cache" audit line (R1
 * non-blocking #1 in the original hook) is surfaced via `auditLines` rather
 * than a direct `process.stdout.write` — same information, dispatcher-owned
 * stdout.
 *
 * @see .minsky/hooks/registry.ts — the guard-dispatcher registration
 * @see .minsky/hooks/dispatch-userpromptsubmit.ts — the dispatcher entrypoint
 */
export function run(input: ClaudeHookInput, _ctx: DispatchContext): GuardOutcome | null {
  if (isOverrideTruthy(process.env[DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV])) {
    return {
      auditLines: [
        `[inject-dispatch-watchdog] override active: ${DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV}=${process.env[DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV]} at ${new Date().toISOString()}\n`,
      ],
    };
  }
  if (input.hook_event_name !== "UserPromptSubmit") return null;

  let cacheResult: CacheReadResult;
  try {
    cacheResult = readCache(getDispatchWatchdogCachePath());
  } catch {
    return null;
  }

  const auditLines: string[] = [];
  if (cacheResult.kind === "malformed") {
    auditLines.push(
      `[inject-dispatch-watchdog] cache file present but malformed at ${getDispatchWatchdogCachePath()} — skipping injection at ${new Date().toISOString()}\n`
    );
  }

  const record = cacheResult.kind === "ok" ? cacheResult.record : null;
  const additionalContext = formatDispatchWatchdogState(record);
  if (additionalContext === null) {
    return auditLines.length > 0 ? { auditLines } : null;
  }

  return { additionalContext, ...(auditLines.length > 0 ? { auditLines } : {}) };
}

async function main(): Promise<void> {
  if (isOverrideTruthy(process.env[DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV])) {
    const auditLine = `[inject-dispatch-watchdog] override active: ${DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV}=${process.env[DISPATCH_WATCHDOG_INJECTION_OVERRIDE_ENV]} at ${new Date().toISOString()}`;
    process.stdout.write(`${auditLine}\n`);
    return;
  }

  let input: UserPromptSubmitInput;
  try {
    input = await readInput<UserPromptSubmitInput>();
  } catch {
    return;
  }
  if (input.hook_event_name !== "UserPromptSubmit") return;

  let cacheResult: CacheReadResult;
  try {
    cacheResult = readCache(getDispatchWatchdogCachePath());
  } catch {
    return;
  }

  // R1 non-blocking #1: a MALFORMED cache (file exists, content doesn't parse)
  // is a distinct signal from a routine MISSING cache (pre-first-sweep-tick,
  // silent/expected) — audit it once per invocation, non-JSON per the
  // sibling-hook audit convention (Claude Code's parser ignores non-JSON
  // stdout lines rather than treating them as a HookOutput envelope).
  if (cacheResult.kind === "malformed") {
    process.stdout.write(
      `[inject-dispatch-watchdog] cache file present but malformed at ${getDispatchWatchdogCachePath()} — skipping injection at ${new Date().toISOString()}\n`
    );
  }

  const record = cacheResult.kind === "ok" ? cacheResult.record : null;
  const additionalContext = formatDispatchWatchdogState(record);
  if (additionalContext === null) return; // nothing flagged — stay silent

  const output: HookOutput = {
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext,
    },
  };
  writeOutput(output);
}

if (import.meta.main) {
  await main();
}
